/* YONDO prototype: gifts (customer), companion flow, vendor flow, hi-fi screen seeding, boot. */
(function () {
  const Y = YAPP, L = YL, M = YM, C = YC, D = M.demo, { S, call, A, F, on, go, toast, dlg, closeDlg, rerender, errBox, money, when, hhmm, esc, $, $$, field, serverFieldErrs, fieldErrs, svcName, OFF, TZ } = Y;
  const confirmDlg = (title, text, label, a) => dlg(`<h2 id="dt">${title}</h2><p class="mu" style="margin:8px 0 16px">${text}</p><div class="col" id="fe" role="alert">${C.Button(label, { a, variant: 'danger' })}${C.Button('Orqaga', { a: 'close', variant: 'sec' })}</div>`);
  const errDlg = (e) => { const f = $('#fe'); if (f) f.innerHTML = errBox(e, false); else toast(L.classify(e).text); };
  const stLabel = { draft: 'Qoralama', submitted: 'Yuborilgan', approved: 'Tasdiqlangan', rejected: 'Rad etilgan', withdrawn: 'Qaytarib olingan', pending: 'Koʻrib chiqilmoqda', unknown: 'Maʼlum emas', verified: 'Tasdiqlangan' };
  const stBadge = (s) => `<span class="stc">${stLabel[s] || esc(s)}</span>`;

  // ================= customer: gifts (cart + offline test order) =================
  S.gf = { delivery: 'pickup', note: '', err: '', last: null };
  async function giftData() { const [prods, cart, orders] = await Promise.all([call('GET', '/gifts/products'), call('GET', '/gifts/cart'), call('GET', '/gifts/test-orders').catch(() => [])]); return { prods, cart, orders }; }
  function giftsHtml(d) {
    const { prods, cart, orders } = d, byId = Object.fromEntries(prods.map((p) => [p.id, p])), sub = cart.reduce((a, c) => a + (byId[c.product_id] ? byId[c.product_id].price_minor * c.quantity : 0), 0), g = S.gf;
    return `<div class="pad col"><h1>Gul va sovgʻalar</h1><div class="ban" style="margin:0">DEMO mahsulotlar. Buyurtma <b>test rejimida</b>: haqiqiy pul yechilmaydi va yetkazib berish operator tomonidan qoʻlda bajariladi.</div>
${prods.length ? `<div class="list g2 st">${prods.map((p, i) => { const q = (cart.find((c) => c.product_id === p.id) || {}).quantity || 0; return C.Card(`<span class="grow col" style="gap:4px"><b>${esc(p.name)}</b><span class="sm mu">${L.GIFT_LABEL[p.category] || esc(p.category)}</span><b>${money(p.price_minor, p.currency)}</b>${p.stock ? '' : '<span class="sm mu">Tugagan</span>'}</span>${q ? `<span class="row"><button class="ib" data-a="gq:${p.id}:${q - 1}" aria-label="Kamaytirish">−</button><b aria-label="${q} dona">${q}</b><button class="ib" data-a="gq:${p.id}:${q + 1}" aria-label="Koʻpaytirish">+</button></span>` : C.Button(p.stock ? 'Savatga' : 'Tugagan', { a: 'gq:' + p.id + ':1', disabled: !p.stock, variant: 'sec' })}`, { up: true }); }).join('')}</div>` : C.Empty('Mahsulotlar yoʻq', 'Hozircha sotuvda sovgʻa yoʻq.')}
<h2>Savat</h2>${cart.length ? `<div class="card col">${cart.map((c) => `<div class="pl"><span>${esc((byId[c.product_id] || {}).name || '?')} × ${c.quantity}</span><span>${byId[c.product_id] ? money(byId[c.product_id].price_minor * c.quantity, 'UZS') : ''}</span></div>`).join('')}<div class="pl tot"><span>Savat boʻyicha taxminiy oraliq jami</span><span>${money(sub, 'UZS')}</span></div><p class="cap mu">Bu hisob-kitob emas: yakuniy summa, yetkazib berish haqi va toʻlov serverdan keladi (hozircha aniqlanmagan).</p></div>
<form data-f="gift" class="col" novalidate><fieldset style="border:0;padding:0;margin:0"><legend class="lb" style="padding:0">Qanday olinadi?</legend><label class="chk"><input type="radio" name="dm" value="pickup"${g.delivery === 'pickup' ? ' checked' : ''}> Oʻzim olib ketaman</label><label class="chk"><input type="radio" name="dm" value="manual_delivery"${g.delivery === 'manual_delivery' ? ' checked' : ''}> Yetkazib berish (operator qoʻlda)</label></fieldset>${C.Field('note', 'Yetkazib berish izohi', { area: true, value: g.note, max: 512, err: g.err, hint: 'Yetkazib berish uchun manzil va izoh majburiy.' })}<button class="btn full" type="submit">Test buyurtma berish</button></form>` : '<p class="sm mu">Savat boʻsh.</p>'}
${g.last ? `<div class="alert success" role="status"><div class="alert-b"><b>Test buyurtma yaratildi</b><br>Haqiqiy pul yechilmadi (real_money_moved: ${g.last.real_money_moved}). Holat: ${esc(g.last.status)}. </div><div class="pl"><span>Oraliq jami (server)</span><span>${money(g.last.subtotal_minor, g.last.currency)}</span></div><div class="pl"><span>Yetkazib berish haqi (server)</span><span>${money(g.last.delivery_fee_minor, g.last.currency) || 'Aniqlanmagan'}</span></div><div class="pl"><span>Toʻlov summasi (server)</span><span>${money(g.last.payable_total_minor, g.last.currency) || 'Aniqlanmagan'}</span></div></div>` : ''}
${orders.length ? `<h2>Test buyurtmalarim</h2><div class="list st">${orders.map((o) => C.Card(`<span class="grow col" style="gap:2px"><b>${o.items.map((i) => esc(i.name_snapshot) + ' × ' + i.quantity).join(', ')}</b><span class="sm mu">${money(o.subtotal_minor, o.currency)} · ${o.delivery_method === 'pickup' ? 'oʻzi olib ketadi' : 'yetkazib berish'}</span></span><span class="demo">TEST</span>`)).join('')}</div>` : ''}</div>`;
  }
  on(/^\/gifts$/, 'customer', async () => giftsHtml(await giftData()), 'gifts');
  const regift = async () => { try { const d = await giftData(); rerender(() => giftsHtml(d)); } catch (e) { toast(L.classify(e).text); } };
  A.gq = async (x) => { const [id, q] = x.split(':'); try { if (+q <= 0) await call('DELETE', '/gifts/cart/' + id); else await call('PUT', '/gifts/cart/' + id, { body: { quantity: +q } }); } catch (e) { toast(L.classify(e).text); } await regift(); };
  F.gift = async (f) => { const g = S.gf; g.delivery = (f.elements.dm.value) || 'pickup'; g.note = field(f, 'note'); g.err = ''; try { g.last = await call('POST', '/gifts/test-orders', { body: { delivery_method: g.delivery, delivery_note: g.note.trim() || null } }); g.note = ''; await regift(); } catch (e) { const c = L.classify(e); if (c.code === 'gift_delivery_note_required') g.err = c.text; else toast(c.text); await regift(); if (g.err) { const n = $('#note'); if (n) n.focus(); } } };

  // ================= companion flow (uses /companions/me/*) =================
  const cwrap = (title, body) => `<div class="pad col"><h1>${title}</h1>${body}</div>`;
  on(/^\/me$/, 'companion', async () => {
    const st = await call('GET', '/companions/me/status'); const [app, prof] = await Promise.all([call('GET', '/companions/me/application').catch(() => null), call('GET', '/companions/me/profile').catch(() => null)]);
    const row = (t, s) => `<div class="pl"><span>${t}</span>${stBadge(s)}</div>`;
    return cwrap('Holat', `${st.publicly_active ? C.Alert('success', 'Profilingiz mijozlarga koʻrinadi.', { title: 'Faol' }) : C.Alert('info', 'Profil hali mijozlarga koʻrinmaydi.', { title: 'Faol emas' })}
<div class="card col">${row('Ariza', st.application_status)}${row('Shaxs tasdiqlash', st.identity_status)}${row('Profil kontenti', st.content_status)}${row('Hisob', st.account_status === 'active' ? 'approved' : st.account_status)}</div>
${st.blockers.length ? `<div class="card col"><b>Faollashtirishga toʻsiqlar</b><ul style="margin:0;padding-left:20px">${st.blockers.map((b) => `<li class="sm">${L.BLOCKER[b] || esc(b)}</li>`).join('')}</ul></div>` : ''}
<p class="cap mu">Ariza tasdiqlanishi, shaxs tekshiruvi va kontent tasdiqlanishi alohida jarayonlar. Hech biri “faol profil” degani emas.</p>
<div class="col">${!app ? `<form data-f="app" class="col" novalidate>${C.Field('statement', 'Ariza matni', { area: true, max: 4000, hint: 'Oʻzingiz haqingizda qisqacha.' })}<button class="btn full" type="submit">Ariza yaratish</button></form>` : ''}
${app && app.status === 'draft' ? C.Button('Arizani yuborish', { a: 'appsub', full: true }) : ''}${app && !prof ? C.Button('Profil yaratish', { a: 'go:#/me/profile', full: true }) : ''}${prof && prof.content_status === 'draft' ? C.Button('Profilni tekshiruvga yuborish', { a: 'profsub', full: true }) : ''}
${prof ? C.Button(st.activation_requested ? 'Faollashtirishni bekor qilish' : 'Faollashtirishni soʻrash', { a: st.activation_requested ? 'deact' : 'act', variant: 'sec', full: true }) : ''}${C.Button('Daromad', { a: 'go:#/me/earnings', variant: 'sec', full: true })}</div>
<details class="card col"><summary style="min-height:44px;display:flex;align-items:center;cursor:pointer"><b>DEMO: administrator qarori</b></summary><p class="cap mu">Haqiqiy ilovada ariza, shaxs va kontentni administrator tasdiqlaydi.</p>${C.Button('Hammasini tasdiqlash (demo)', { a: 'adm', variant: 'sec' })}</details>`);
  }, 'me');
  const reMe = () => Y.route();
  F.app = async (f) => { try { await call('POST', '/companions/me/application', { body: { statement: field(f, 'statement') } }); toast('Ariza yaratildi.'); reMe(); } catch (e) { toast(L.classify(e).text); } };
  A.appsub = async () => { try { await call('POST', '/companions/me/application/submit'); toast('Ariza yuborildi.'); reMe(); } catch (e) { toast(L.classify(e).text); } };
  A.profsub = async () => { try { await call('POST', '/companions/me/profile/submit'); toast('Profil tekshiruvga yuborildi.'); reMe(); } catch (e) { toast(L.classify(e).text); } };
  A.act = async () => { try { await call('POST', '/companions/me/activate'); toast('Faollashtirish soʻraldi.'); reMe(); } catch (e) { toast(L.classify(e).text); } };
  A.deact = async () => { try { await call('POST', '/companions/me/deactivate'); toast('Faollashtirish bekor qilindi.'); reMe(); } catch (e) { toast(L.classify(e).text); } };
  A.adm = () => { D.adminApprove(); toast('Tasdiqlandi (DEMO).'); reMe(); };
  on(/^\/me\/earnings$/, 'companion', () => cwrap('Daromad', C.Alert('info', 'Hamroh daromadi uchun jonli maʼlumot manbai hali ulanmagan. Bu yerda raqamlar koʻrsatilmaydi.', { title: 'Hali jonli emas' }) + C.Button('Holatga qaytish', { a: 'go:#/me', variant: 'sec' })), 'me');

  const csv = (s) => s.split(',').map((x) => x.trim()).filter(Boolean);
  const profForm = (p, errs, top) => `<form data-f="prof" class="col" novalidate>${top || ''}${C.Field('display_name', 'Koʻrsatiladigan ism', { value: p.display_name, required: true, max: 128, err: errs.display_name })}${C.Field('bio', 'Oʻzingiz haqingizda', { area: true, value: p.bio, max: 8000, err: errs.bio, rows: 4 })}${C.Field('interests', 'Qiziqishlar (vergul bilan)', { value: (p.interests || []).join(', '), err: errs.interests, hint: 'Har biri 1–64 belgi, takrorlanmasin.' })}${C.Field('languages', 'Tillar (vergul bilan)', { value: (p.languages || []).join(', '), err: errs.languages })}<div class="card col"><b>Fotosuratlar</b><p class="sm mu">Rasm yuklash prototipda ulanmagan. Haqiqiy ilovada rasmlar serverda qayta ishlanadi va koʻrib chiqiladi.</p></div><button class="btn full" type="submit">Saqlash</button></form>`;
  on(/^\/me\/profile$/, 'companion', async () => { const p = await call('GET', '/companions/me/profile').catch((e) => { if (e.code === 'profile_not_found') return null; throw e; }); Y.S.prof = p; return cwrap(p ? 'Profil' : 'Profil yaratish', (p ? `<p class="sm mu">Tahrirlangan profil qayta tekshiruvga tushadi (holat: ${stLabel[p.content_status] || p.content_status}).</p>` : '<p class="sm mu">Profil yaratish uchun avval ariza yarating (Holat sahifasi).</p>') + profForm(p || { display_name: '', bio: '', interests: [], languages: [] }, {})); }, 'prof');
  F.prof = async (f) => { const p = { display_name: field(f, 'display_name'), bio: field(f, 'bio'), interests: csv(field(f, 'interests')), languages: csv(field(f, 'languages')) }; const v = L.validateProfile(p); if (v.length) { rerender(() => cwrap('Profil', profForm(p, fieldErrs(v), C.Alert('error', 'Maydonlarni tekshiring.', { title: 'Saqlab boʻlmadi' })))); const a = $('[role=alert]'); if (a) { a.setAttribute('tabindex', '-1'); a.focus(); } return; } try { await call(Y.S.prof ? 'PUT' : 'POST', '/companions/me/profile', { body: p }); toast('Profil saqlandi.'); Y.route(); } catch (e) { const c = L.classify(e), se = serverFieldErrs(e); rerender(() => cwrap('Profil', profForm(p, se, errBox(e, false)))); const a = $('[role=alert]'); if (a) { a.setAttribute('tabindex', '-1'); a.focus(); } } };

  const svcForm = (s, errs) => `<h2 id="dt">${s.id ? 'Xizmatni tahrirlash' : 'Yangi xizmat'}</h2><form data-f="svc" data-id="${s.id || ''}" class="col" novalidate style="margin-top:8px">${C.Field('service_code', 'Xizmat turi', { options: Object.entries(L.SERVICE_LABEL), value: s.service_code || 'coffee', err: errs.service_code })}${C.Field('price', 'Narx (soʻm)', { mode: 'decimal', value: s.price_minor != null ? L.somInput(s.price_minor) : (s.price_text || ''), err: errs.price_minor, required: true, hint: 'Tiyin 2 xonagacha: 55000 yoki 55000,50' })}${C.Field('unit_minutes', 'Birlik (daqiqa)', { options: [30, 60, 90, 120].map((m) => [m, m + ' daqiqa']), value: s.unit_minutes || 60, err: errs.unit_minutes, hint: 'Mijoz bronining davomiyligi shu birlikka karrali boʻladi.' })}${C.Field('description', 'Tavsif', { area: true, value: s.description, max: 4000, err: errs.description })}<div id="fe" role="alert"></div><button class="btn full" type="submit">Saqlash</button><button class="btn sec full" type="button" data-a="close">Bekor qilish</button></form>`;
  on(/^\/me\/services$/, 'companion', async () => { const l = await call('GET', '/companions/me/services'); S.msvc = l; return cwrap('Xizmatlar', `${l.length ? `<div class="list st">${l.map((s) => C.Card(`<span class="grow col" style="gap:2px"><b>${svcName(s.service_code)}</b><span class="sm mu">${esc(s.description || '')}</span><b>${money(s.price_minor, s.currency)} / ${s.unit_minutes} daq</b></span><span class="col" style="gap:8px"><button class="btn sec" data-a="svced:${s.id}">Tahrirlash</button><button class="btn danger" data-a="svcdel:${s.id}">Oʻchirish</button></span>`)).join('')}</div>` : C.Empty('Hali xizmat yoʻq', 'Mijozlar bron qilishi uchun kamida bitta xizmat qoʻshing.')}${C.Button('Xizmat qoʻshish', { a: 'svcnew', full: true })}`); }, 'svcs');
  A.svcnew = () => dlg(svcForm({}, {})); A.svced = (id) => dlg(svcForm(S.msvc.find((s) => s.id === id), {}));
  A.svcdel = (id) => confirmDlg('Xizmatni oʻchirish', 'Mavjud bronlarga taʼsir qilmaydi.', 'Oʻchirish', 'svcdelgo:' + id);
  A.svcdelgo = async (id) => { try { await call('DELETE', '/companions/me/services/' + id); closeDlg(); toast('Oʻchirildi.'); Y.route(); } catch (e) { errDlg(e); } };
  F.svc = async (f) => { const pm = L.toMinor(f.elements.price.value); const s = { service_code: field(f, 'service_code'), price_minor: pm.ok ? pm.minor : NaN, unit_minutes: +field(f, 'unit_minutes'), currency: 'UZS', description: field(f, 'description') }; const v = L.validateService(s); if (!pm.ok) { const k = v.findIndex((x) => x.field === 'price_minor'); const m = { field: 'price_minor', text: L.AMOUNT_ERR[pm.code] }; if (k >= 0) v[k] = m; else v.push(m); } if (v.length) { dlg(svcForm(Object.assign({ id: f.dataset.id }, s, { price_minor: isNaN(s.price_minor) ? null : s.price_minor, price_text: f.elements.price.value }), fieldErrs(v))); return; } try { await call(f.dataset.id ? 'PUT' : 'POST', '/companions/me/services' + (f.dataset.id ? '/' + f.dataset.id : ''), { body: s }); closeDlg(); toast('Xizmat saqlandi.'); Y.route(); } catch (e) { const se = serverFieldErrs(e); if (L.classify(e).code === 'invalid_price') se.price_minor = L.classify(e).text; if (Object.keys(se).length) dlg(svcForm(Object.assign({ id: f.dataset.id }, s), se)); else errDlg(e); } };

  const availForm = (d, errs) => `<form data-f="avail" class="col" novalidate>${C.Field('date', 'Sana', { type: 'date', value: d.date, err: errs.starts_at })}<div class="row wrap"><div class="grow">${C.Field('from', 'Boshlanish', { type: 'time', value: d.from || '10:00' })}</div><div class="grow">${C.Field('to', 'Tugash', { type: 'time', value: d.to || '18:00', err: errs.ends_at })}</div></div><p class="cap mu">Vaqt zonasi: ${TZ}. Mijozlar faqat shu oraliqlarga bron qila oladi.</p><div id="fe" role="alert"></div><button class="btn full" type="submit">Vaqt qoʻshish</button></form>`;
  on(/^\/me\/availability$/, 'companion', async () => { const l = (await call('GET', '/companions/me/availability')).sort((a, b) => (a.starts_at < b.starts_at ? -1 : 1)); return cwrap('Ish vaqtlari', `${l.length ? `<div class="list st">${l.map((a) => C.Card(`<span class="grow col" style="gap:2px"><b>${when(a.starts_at)} – ${hhmm(Date.parse(a.ends_at))}</b><span class="cap mu">${esc(a.timezone)}</span></span><button class="btn danger" data-a="avdel:${a.id}" aria-label="${when(a.starts_at)} vaqtini oʻchirish">Oʻchirish</button>`)).join('')}</div>` : C.Empty('Ish vaqti belgilanmagan', 'Vaqt qoʻshmasangiz, mijozlar bron qila olmaydi.')}<h2>Yangi vaqt</h2>${availForm({ date: '' }, {})}`); }, 'avail');
  F.avail = async (f) => { const d = field(f, 'date'), from = field(f, 'from'), to = field(f, 'to'); const mk = (t) => { const ms = d && t ? Date.parse(d + 'T' + t + ':00Z') : NaN; return isNaN(ms) ? '' : new Date(ms - OFF).toISOString(); }; const a = { starts_at: mk(from), ends_at: mk(to), timezone: TZ }; const v = L.validateAvailability(a); if (!d) v.unshift({ field: 'starts_at', text: 'Sanani tanlang.' }); if (v.length) { rerender(() => cwrap('Ish vaqtlari', availForm({ date: d, from, to }, fieldErrs(v)))); return; } try { await call('POST', '/companions/me/availability', { body: a }); toast('Vaqt qoʻshildi.'); Y.route(); } catch (e) { const se = serverFieldErrs(e); if (Object.keys(se).length) rerender(() => cwrap('Ish vaqtlari', availForm({ date: d, from, to }, { ends_at: se.ends_at || se.starts_at }))); else { const b = $('#fe'); if (b) b.innerHTML = errBox(e, false); } } };
  A.avdel = (id) => confirmDlg('Vaqtni oʻchirish', 'Bu oraliqqa yangi bronlar qabul qilinmaydi.', 'Oʻchirish', 'avdelgo:' + id);
  A.avdelgo = async (id) => { try { await call('DELETE', '/companions/me/availability/' + id); closeDlg(); toast('Oʻchirildi.'); Y.route(); } catch (e) { errDlg(e); } };

  on(/^\/me\/requests$/, 'companion', async () => { const l = await call('GET', '/bookings'); return cwrap('Soʻrovlar', `${l.length ? `<div class="list g2 st">${l.map((b) => C.Card(`<span class="grow col" style="gap:2px"><b>${svcName(b.service_code)}</b><span class="sm mu">${when(b.starts_at)} · ${b.duration_minutes} daq · mijoz #${esc(b.customer_id.slice(-4))}</span><span class="sm">${money(b.price_minor, b.currency)}</span></span>${C.Status(L.LABEL[b.status], b.status)}`, { a: 'go:#/b/' + b.id })).join('')}</div>` : C.Empty('Soʻrovlar yoʻq', 'Faol profilga mijozlar soʻrov yuboradi.')}<details class="card col"><summary style="min-height:44px;display:flex;align-items:center;cursor:pointer"><b>DEMO</b></summary><p class="cap mu">Mijoz soʻrovlarini simulyatsiya qiladi.</p>${C.Button('Demo soʻrovlar qoʻshish', { a: 'dreq', variant: 'sec' })}</details>`); }, 'req');
  A.dreq = () => { D.incomingRequests(); Y.route(); };

  // ================= vendor flow (gift products) =================
  const prodForm = (p, errs) => `<h2 id="dt">${p.id ? 'Mahsulotni tahrirlash' : 'Yangi mahsulot'}</h2><form data-f="prod" data-id="${p.id || ''}" class="col" novalidate style="margin-top:8px">${C.Field('name', 'Nomi', { value: p.name, max: 160, required: true, err: errs.name })}${C.Field('category', 'Kategoriya', { options: Object.entries(L.GIFT_LABEL), value: p.category || 'flowers' })}${C.Field('price', 'Narx (soʻm)', { mode: 'decimal', value: p.price_minor != null ? L.somInput(p.price_minor) : (p.price_text || ''), err: errs.price_minor, required: true, hint: 'Tiyin 2 xonagacha: 120000 yoki 120000,50' })}${C.Field('stock', 'Zaxira (dona)', { type: 'number', mode: 'numeric', min: 0, step: 1, value: p.stock != null ? p.stock : '', err: errs.stock, required: true })}${C.Field('description', 'Tavsif', { area: true, value: p.description, err: errs.description, required: true })}<div id="fe" role="alert"></div><button class="btn full" type="submit">Saqlash</button><button class="btn sec full" type="button" data-a="close">Bekor qilish</button></form>`;
  on(/^\/v$/, 'vendor', async () => { const [sm, l] = await Promise.all([call('GET', '/vendor/summary'), call('GET', '/gifts/vendor/products')]); S.vprods = l; const kv = Object.entries(sm || {}).filter(([, v]) => typeof v === 'number'); return cwrap('Mahsulotlarim', `${kv.length ? `<div class="card col">${kv.map(([k, v]) => `<div class="pl"><span class="mu">${{ products_total: 'Jami mahsulot', products_published: 'Eʼlon qilingan' }[k] || esc(k)}</span><b>${v}</b></div>`).join('')}</div>` : ''}${l.length ? `<div class="list g2 st">${l.map((p) => C.Card(`<span class="grow col" style="gap:4px"><b>${esc(p.name)}</b><span class="sm mu">${L.GIFT_LABEL[p.category] || esc(p.category)} · zaxira ${p.stock}</span><b>${money(p.price_minor, p.currency)}</b>${p.published ? '<span class="bdg">Eʼlon qilingan</span>' : '<span class="bdg off">Eʼlon qilinmagan</span>'}</span><span class="col" style="gap:8px"><button class="btn sec" data-a="pred:${p.id}">Tahrirlash</button>${p.published ? `<button class="btn sec" data-a="punp:${p.id}">Yashirish</button>` : `<button class="btn sec" data-a="ppub:${p.id}">DEMO: eʼlon qilish</button>`}</span>`)).join('')}</div>` : C.Empty('Hali mahsulot yoʻq', 'Birinchi mahsulotingizni qoʻshing.')}${C.Button('Mahsulot qoʻshish', { a: 'pnew', full: true })}<p class="cap mu">Eʼlon qilish administrator tasdigʻidan keyin (demoda tugma bilan).</p>`); }, 'v');
  A.pnew = () => dlg(prodForm({}, {})); A.pred = (id) => dlg(prodForm(S.vprods.find((p) => p.id === id), {}));
  A.ppub = (id) => { D.adminPublish(id); toast('Eʼlon qilindi (DEMO).'); Y.route(); };
  A.punp = async (id) => { try { await call('POST', '/vendor/products/' + id + '/unpublish'); toast('Yashirildi.'); Y.route(); } catch (e) { toast(L.classify(e).text); } };
  F.prod = async (f) => { const pm = L.toMinor(f.elements.price.value), st = f.elements.stock.value; const p = { name: field(f, 'name'), category: field(f, 'category'), price_minor: pm.ok ? pm.minor : NaN, stock: st === '' ? NaN : Math.floor(Number(st)), currency: 'UZS', description: field(f, 'description') }; const v = L.validateProduct(p); if (!pm.ok) { const k = v.findIndex((x) => x.field === 'price_minor'); const m = { field: 'price_minor', text: L.AMOUNT_ERR[pm.code] }; if (k >= 0) v[k] = m; else v.push(m); } if (v.length) { dlg(prodForm(Object.assign({ id: f.dataset.id }, p, { price_minor: isNaN(p.price_minor) ? null : p.price_minor, price_text: f.elements.price.value, stock: isNaN(p.stock) ? null : p.stock }), fieldErrs(v))); return; } try { await call(f.dataset.id ? 'PATCH' : 'POST', f.dataset.id ? '/vendor/products/' + f.dataset.id : '/gifts/vendor/products', { body: p }); closeDlg(); toast('Mahsulot saqlandi.'); Y.route(); } catch (e) { errDlg(e); } };
  on(/^\/v\/orders$/, 'vendor', async () => { const l = await call('GET', '/vendor/orders'); return cwrap('Buyurtmalar', Array.isArray(l) && l.length ? `<div class="list st">${l.map((o) => C.Card(`<span class="grow col"><b>Buyurtma #${esc(String(o.id || '').slice(-4))}</b><span class="sm mu">${esc(o.status || '')}</span></span>`)).join('')}</div>` : C.Empty('Buyurtmalar yoʻq', 'Mijozlar sizning mahsulotingizni buyurtma qilganda shu yerda koʻrinadi.') + '<p class="cap mu">Buyurtma maʼlumotlari sxemasi hujjatlashtirilmagan; prototip uni ehtiyotkorlik bilan koʻrsatadi.</p>'); }, 'vo');
  on(/^\/v\/earnings$/, 'vendor', async () => { try { await call('GET', '/vendor/earnings'); return cwrap('Daromad', C.Alert('info', 'Maʼlumot qaytdi, lekin sxemasi hujjatlashtirilmagan.')); } catch (e) { if (e.status === 503) return cwrap('Daromad', errBox(e, true)); throw e; } }, 've');

  // ================= hi-fi screens (seeded, independently openable) =================
  async function ensureSession(roles) { if (Y.S.authed) return; await call('POST', '/auth/otp/request', { body: { phone_number: '+998901234567' } }); await call('POST', '/auth/otp/verify', { body: { phone_number: '+998901234567', code: '1234' } }); await call('PUT', '/auth/roles', { body: { roles } }); Y.S.me = await call('GET', '/auth/me'); Y.S.authed = true; Y.S.roles = roles; Y.S.role = roles[0]; Y.shell(); }
  const day1 = (h) => Y.dayStart(1) + h * 36e5;
  async function seedActive() { const prevFee = D.cfg.feeBps; D.cfg.feeBps = 1000; /* DEMO fixture, restored below */ try { return await seedActive_(); } finally { D.cfg.feeBps = prevFee; } }
  async function seedActive_() { const pg = await call('GET', '/discovery/companions', { query: { q: 'Madina' } }), c = pg.items[0]; let b = null; for (let d = 1; d <= 6 && !b; d++) { try { b = await call('POST', '/bookings', { body: { service_id: c.services[0].id, starts_at: new Date(Y.dayStart(d) + 12 * 36e5).toISOString(), duration_minutes: 60, meeting_place: 'Amir Temur xiyoboni', timezone: TZ } }); } catch (e) { if (!['availability_not_found', 'booking_time_unavailable'].includes(e.code)) throw e; } } if (!b) throw new Error('availability_not_found'); D.companionAccept(b.id); const p = await call('POST', '/payments/bookings/' + b.id, { headers: { 'Idempotency-Key': L.idemKey() } }); D.providerComplete(p.id, 'succeeded'); D.skipToStart(b.id); await call('POST', '/meetings/bookings/' + b.id + '/check-in'); D.companionCheckIn(b.id); await call('POST', '/meetings/bookings/' + b.id + '/start'); await call('POST', '/chat/bookings/' + b.id + '/messages', { body: { body: 'Salom! Men kirish oldidaman.' } }); return b; }
  Y.seedScreen = async function (name) {
    try { await ensureSession(['customer']); const pg = await call('GET', '/discovery/companions', { query: { limit: 30 } }); const first = pg.items[0];
      const t = { home: '#/home', search: '#/search?service_code=coffee', profile: '#/c/' + first.id, booking: '#/book/' + first.id, gifts: '#/gifts' }[name];
      if (name === 'chat') { const b = await seedActive(); return location.replace('#/b/' + b.id); }
      if (!t) return location.replace('#/home'); location.replace(t);
    } catch (e) { Y.swap(`<div class="pad col"><h1>Ekran tayyorlanmadi</h1>${errBox(e)}</div>`); }
  };
  // ---- boot ----
  if (!location.hash) history.replaceState(null, '', '#/');
  Y.shell(); Y.route();
})();
